/** Validation message for a missing or malformed email field. */
export const EMAIL_INVALID_MESSAGE = "email must be a valid address";

/** Validation message for a missing or malformed name field. */
export const NAME_REQUIRED_MESSAGE = "name is required";

/** Validation message for a malformed age field. */
export const AGE_INVALID_MESSAGE = "age must be a non-negative integer";

/** Validation message for a request body that is not a JSON object. */
export const BODY_INVALID_MESSAGE = "request body must be a JSON object";

const EMAIL_ADDRESS_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Validated create-user payload. */
export interface CreateUser {
  email: string;
  name: string;
  age?: number;
}

/** Outcome of {@link parseCreateUser}. */
export type ParseCreateUserResult =
  | { ok: true; value: CreateUser }
  | { ok: false; errors: string[] };

/** Outcome of {@link validateCreateUser}. */
export interface ValidationResult {
  ok: boolean;
  errors: string[];
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Parses and validates a create-user request at the API boundary.
 *
 * @param input - Untrusted request data decoded from JSON.
 * @returns The normalized payload when valid, otherwise the validation errors.
 */
export function parseCreateUser(input: unknown): ParseCreateUserResult {
  if (!isRecord(input)) {
    return { ok: false, errors: [BODY_INVALID_MESSAGE] };
  }

  const errors: string[] = [];

  const email = typeof input.email === "string" ? input.email.trim() : "";
  if (!EMAIL_ADDRESS_PATTERN.test(email)) {
    errors.push(EMAIL_INVALID_MESSAGE);
  }

  const name = typeof input.name === "string" ? input.name.trim() : "";
  if (name.length === 0) {
    errors.push(NAME_REQUIRED_MESSAGE);
  }

  const age = input.age;
  if (age !== undefined) {
    if (typeof age !== "number" || !Number.isInteger(age) || age < 0) {
      errors.push(AGE_INVALID_MESSAGE);
    }
  }

  if (errors.length > 0) {
    return { ok: false, errors };
  }

  const value: CreateUser = { email, name };
  if (typeof age === "number") {
    value.age = age;
  }
  return { ok: true, value };
}

/**
 * Validates a create-user request at the API boundary.
 *
 * @param input - Untrusted request data.
 * @returns Whether the input is valid and the list of validation errors.
 */
export function validateCreateUser(input: unknown): ValidationResult {
  const result = parseCreateUser(input);
  if (result.ok) {
    return { ok: true, errors: [] };
  }
  return { ok: false, errors: result.errors };
}

