import { test } from "node:test";
import assert from "node:assert/strict";

import {
  validateCreateUser,
  EMAIL_INVALID_MESSAGE,
  NAME_REQUIRED_MESSAGE,
  AGE_INVALID_MESSAGE,
  BODY_INVALID_MESSAGE,
} from "./validation.js";
import {
  handleCreateUserRequest,
  HTTP_BAD_REQUEST,
  HTTP_CREATED,
} from "./endpoint.js";
import { lineTotal, orderTotal } from "./pricing.js";
import { loadOrders, type OrderStore } from "./repository.js";
import { resolveUserFile, BASE_DIR } from "./files.js";

test("validates a valid user", () => {
  assert.deepEqual(validateCreateUser({ email: "a@b.co", name: "Ada", age: 30 }), {
    ok: true,
    errors: [],
  });
});

test("rejects a missing email", () => {
  const result = validateCreateUser({ name: "Ada" });
  assert.equal(result.ok, false);
  assert.match(result.errors.join(","), /email/);
});

test("accepts a valid create-user request", () => {
  assert.deepEqual(handleCreateUserRequest({ email: "a@b.co", name: "Ada", age: 30 }), {
    status: HTTP_CREATED,
    body: { user: { email: "a@b.co", name: "Ada", age: 30 } },
  });
});

test("accepts a create-user request without the optional age", () => {
  assert.deepEqual(handleCreateUserRequest({ email: "a@b.co", name: "Ada" }), {
    status: HTTP_CREATED,
    body: { user: { email: "a@b.co", name: "Ada" } },
  });
});

test("normalizes surrounding whitespace", () => {
  assert.deepEqual(handleCreateUserRequest({ email: " a@b.co ", name: " Ada " }), {
    status: HTTP_CREATED,
    body: { user: { email: "a@b.co", name: "Ada" } },
  });
});

test("returns 400 for a missing email", () => {
  assert.deepEqual(handleCreateUserRequest({ name: "Ada" }), {
    status: HTTP_BAD_REQUEST,
    body: { errors: [EMAIL_INVALID_MESSAGE] },
  });
});

test("returns 400 for a missing name", () => {
  assert.deepEqual(handleCreateUserRequest({ email: "a@b.co" }), {
    status: HTTP_BAD_REQUEST,
    body: { errors: [NAME_REQUIRED_MESSAGE] },
  });
});

test("returns 400 for a malformed email", () => {
  for (const email of ["not-an-email", "a@b", "", " a@b.co "]) {
    assert.deepEqual(handleCreateUserRequest({ email, name: "Ada" }), {
      status: HTTP_BAD_REQUEST,
      body: { errors: [EMAIL_INVALID_MESSAGE] },
    });
  }
});

test("returns 400 for a blank name", () => {
  assert.deepEqual(handleCreateUserRequest({ email: "a@b.co", name: "   " }), {
    status: HTTP_BAD_REQUEST,
    body: { errors: [NAME_REQUIRED_MESSAGE] },
  });
});

test("returns 400 for malformed field types", () => {
  const requests: unknown[] = [
    { email: 1, name: "Ada" },
    { email: "a@b.co", name: ["Ada"] },
    { email: "a@b.co", name: "Ada", age: "30" },
    { email: "a@b.co", name: "Ada", age: 1.5 },
    { email: "a@b.co", name: "Ada", age: -1 },
    { email: "a@b.co", name: "Ada", age: null },
  ];

  for (const request of requests) {
    const response = handleCreateUserRequest(request);
    assert.equal(response.status, HTTP_BAD_REQUEST);
    assert.notEqual(response.body.errors.length, 0);
  }
});

test("reports every invalid field in one response", () => {
  assert.deepEqual(handleCreateUserRequest({}), {
    status: HTTP_BAD_REQUEST,
    body: { errors: [EMAIL_INVALID_MESSAGE, NAME_REQUIRED_MESSAGE] },
  });
});

test("returns 400 for a non-object request body", () => {
  for (const request of [null, undefined, "Ada", [], 42]) {
    assert.deepEqual(handleCreateUserRequest(request), {
      status: HTTP_BAD_REQUEST,
      body: { errors: [BODY_INVALID_MESSAGE] },
    });
  }
});

test("returns 400 for a non-integer age", () => {
  assert.deepEqual(handleCreateUserRequest({ email: "a@b.co", name: "Ada", age: Number.NaN }), {
    status: HTTP_BAD_REQUEST,
    body: { errors: [AGE_INVALID_MESSAGE] },
  });
});

test("prices taxable and non-taxable items", () => {
  assert.equal(lineTotal({ unitPrice: 10, quantity: 2, taxable: false }), 20);
  assert.equal(lineTotal({ unitPrice: 10, quantity: 2, taxable: true }), 24);
});

test("totals an order", () => {
  assert.equal(
    orderTotal([
      { unitPrice: 10, quantity: 1, taxable: false },
      { unitPrice: 5, quantity: 2, taxable: true },
    ]),
    22,
  );
});

test("loads orders in order", async () => {
  const store: OrderStore = {
    async findById(id) {
      return { id, total: 1 };
    },
  };
  const orders = await loadOrders(store, ["a", "b"]);
  assert.deepEqual(orders.map((o) => o.id), ["a", "b"]);
});

test("resolves a normal file name", () => {
  assert.equal(resolveUserFile("avatar.png"), `${BASE_DIR}/avatar.png`);
});

